log = [
  ("T1", "kassa",   300, 100),
  ("T2", "ball",     50,  30),
  ("T1", "ausflug",   0, 200),
  ("T1", "COMMIT"),
  ("T3", "kassa",   100,  90),
]  # <- Absturz
platte = {"kassa": 90, "ausflug": 0,
          "ball": 30}

fertig = {e[0] for e in log
          if e[1] == "COMMIT"}
# REDO: vorwärts, nur committete TAs
for e in log:
    if len(e) == 4 and e[0] in fertig:
        platte[e[1]] = e[3]
# UNDO: rückwärts, alle anderen
for e in reversed(log):
    if len(e) == 4 and e[0] not in fertig:
        platte[e[1]] = e[2]
print(platte)

# Ausgabe:
# {'kassa': 100, 'ausflug': 200,
#  'ball': 50}
